"""Per-corpus `exclude:` — files in a corpus directory that aren't documents
(default `["README.md"]`), invisible to indexing, lint, and the staleness
fingerprint alike (hq-sl5k)."""

from __future__ import annotations

import sqlite3

from ctx_cli.corpus import DEFAULT_EXCLUDE, iter_corpus_files, load_config
from ctx_cli.indexer import _fingerprint, build_index
from ctx_cli.lint import lint


def _write_readme(rig_dir):
    (rig_dir / "docs" / "decisions" / "README.md").write_text(
        "Generated by strategy export --ctx. Do not edit.\n"
    )


def test_default_excludes_readme_from_iter_corpus_files(rig_dir):
    _write_readme(rig_dir)
    config = load_config(rig_dir / ".ctx")
    decisions = next(c for c in config.corpora if c.name == "decisions")
    assert decisions.exclude == DEFAULT_EXCLUDE
    names = {p.name for p in iter_corpus_files(decisions)}
    assert "README.md" not in names


def test_readme_without_frontmatter_does_not_fail_lint(rig_dir):
    """This is the exact bug the strategy exporter had to work around: a
    README with no frontmatter, sitting in a `decisions` corpus directory,
    must not be an 'ERROR: no parseable frontmatter' — it isn't a document
    at all."""
    _write_readme(rig_dir)
    config = load_config(rig_dir / ".ctx")
    report = lint(config)
    assert report.ok, report.errors
    assert not any("README.md" in e for e in report.errors)


def test_readme_not_indexed(rig_dir):
    _write_readme(rig_dir)
    config = load_config(rig_dir / ".ctx")
    build_index(config)
    conn = sqlite3.connect(config.index_db_path)
    try:
        ids = {r[0] for r in conn.execute("SELECT id FROM documents").fetchall()}
    finally:
        conn.close()
    assert "readme" not in ids
    assert not any("README" in str(i) for i in ids)


def _all_files(config):
    return [(spec, p) for spec in config.corpora for p in iter_corpus_files(spec)]


def test_readme_not_part_of_staleness_fingerprint(rig_dir):
    config = load_config(rig_dir / ".ctx")
    build_index(config)
    before = _fingerprint(config, _all_files(config))

    _write_readme(rig_dir)
    after = _fingerprint(config, _all_files(config))
    assert before == after


def test_explicit_exclude_overrides_default_entirely(rig_dir):
    """`exclude:` replaces the default, it doesn't add to it — an empty list
    un-hides README.md for a corpus that wants it treated as a document."""
    config_path = rig_dir / ".ctx" / "config.yaml"
    text = config_path.read_text()
    text = text.replace(
        "  decisions:\n    type: decisions\n    path: docs/decisions\n",
        "  decisions:\n    type: decisions\n    path: docs/decisions\n    exclude: []\n",
    )
    assert text != config_path.read_text()  # the replace actually matched
    config_path.write_text(text)

    _write_readme(rig_dir)
    config = load_config(rig_dir / ".ctx")
    decisions = next(c for c in config.corpora if c.name == "decisions")
    assert decisions.exclude == []
    names = {p.name for p in iter_corpus_files(decisions)}
    assert "README.md" in names


def test_custom_exclude_glob(rig_dir):
    (rig_dir / "docs" / "decisions" / "draft-001.md").write_text(
        "---\nid: draft-001\ntitle: Draft\nsummary: not ready.\n---\n"
    )
    config_path = rig_dir / ".ctx" / "config.yaml"
    extra = '    exclude: ["draft-*.md"]\n'
    text = config_path.read_text().replace(
        "  decisions:\n    type: decisions\n    path: docs/decisions\n",
        "  decisions:\n    type: decisions\n    path: docs/decisions\n" + extra,
    )
    config_path.write_text(text)

    config = load_config(rig_dir / ".ctx")
    decisions = next(c for c in config.corpora if c.name == "decisions")
    assert decisions.exclude == ["draft-*.md"]
    names = {p.name for p in iter_corpus_files(decisions)}
    assert "draft-001.md" not in names
